import { useState, useEffect } from 'react';

const API = 'http://localhost:5000/api';
const getToken = () => localStorage.getItem('examai_token');

const TYPE_COLORS = {
  info:    { c:'#2563eb', bg:'#dbeafe', border:'#bfdbfe' },
  success: { c:'#16a34a', bg:'#dcfce7', border:'#bbf7d0' },
  warning: { c:'#d97706', bg:'#fef3c7', border:'#fde68a' },
  urgent:  { c:'#dc2626', bg:'#fee2e2', border:'#fecaca' },
};

export default function StudentDashboard({ store, setActivePage }) {
  const [notifs,   setNotifs]   = useState([]);
  const [progress, setProgress] = useState([]);
  const [topRanks, setTopRanks] = useState([]);
  const sid = store.currentStudent?.student_id;

  useEffect(() => {
    fetch(`${API}/notifications`, { headers:{ Authorization:`Bearer ${getToken()}` } })
      .then(r=>r.json()).then(d=>setNotifs(Array.isArray(d)?d.slice(0,3):[])).catch(()=>{});
    if (sid) {
      fetch(`${API}/profile/progress/${sid}`, { headers:{ Authorization:`Bearer ${getToken()}` } })
        .then(r=>r.json()).then(d=>setProgress(Array.isArray(d)?d:[])).catch(()=>{});
    }
    // Load top rankers from first available exam
    fetch(`${API}/exams`, { headers:{ Authorization:`Bearer ${getToken()}` } })
      .then(r=>r.json()).then(async exams => {
        const arr = Array.isArray(exams) ? exams.filter(e=>e.status==='published') : [];
        if (!arr.length) return;
        const board = await fetch(`${API}/exams/${arr[0].exam_id}/leaderboard`, { headers:{ Authorization:`Bearer ${getToken()}` } })
          .then(r=>r.json()).catch(()=>[]);
        setTopRanks(Array.isArray(board)?board.slice(0,5):[]);
      }).catch(()=>{});
  }, [sid]);

  const avgPct    = progress.length ? Math.round(progress.reduce((a,p)=>a+(Number(p.total_score)/Number(p.total_marks)*100),0)/progress.length) : 0;
  const gradeOrder= ['A+','A','B','C','D','F'];
  const bestGrade = progress.length ? progress.reduce((best,p)=>gradeOrder.indexOf(p.grade)<gradeOrder.indexOf(best)?p.grade:best,'F') : '—';
  const gc        = g => g==='A+'||g==='A'?'#16a34a':g==='F'?'#dc2626':g==='B'?'#2563eb':g==='C'?'#d97706':'#6b7280';
  const rankMedal = (i) => i===0?'🥇':i===1?'🥈':i===2?'🥉':null;
  const rankColor = (i) => i===0?'#f59e0b':i===1?'#6b7280':i===2?'#b45309':'#7c3aed';

  return (
    <div className="fade-up">

      {/* ── HERO ── matches image exactly */}
      <div style={{ background:'linear-gradient(135deg,#f0eeff 0%,#e8e4ff 50%,#eef2ff 100%)', border:'1px solid #ddd6fe', borderRadius:16, padding:'28px 32px', marginBottom:20, display:'grid', gridTemplateColumns:'1fr 220px', alignItems:'center', gap:16, boxShadow:'0 1px 4px rgba(0,0,0,.06)' }}>
        <div>
          <div style={{ display:'inline-flex', alignItems:'center', gap:5, background:'rgba(124,58,237,0.08)', border:'1px solid #ddd6fe', borderRadius:20, padding:'3px 12px', fontSize:11, fontWeight:600, color:'#7c3aed', marginBottom:12, letterSpacing:.3 }}>Student Portal</div>
          <h1 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:28, color:'#0f0f1a', marginBottom:8, letterSpacing:-.3 }}>Hello, {store.currentUser.name.split(' ')[0]} 👋</h1>
          <p style={{ fontSize:13, color:'#374151', marginBottom:20, lineHeight:1.65, maxWidth:420 }}>Ready to challenge yourself? Your exams are waiting.<br/>Practice, improve, and conquer your goals.</p>
          <div style={{ display:'flex', gap:10 }}>
            <button onClick={() => setActivePage('available-exams')}
              style={{ padding:'9px 20px', background:'#7c3aed', color:'#fff', borderRadius:8, border:'none', fontWeight:700, fontSize:13, cursor:'pointer', display:'flex', alignItems:'center', gap:8 }}>
              Browse Exams <span style={{ fontSize:14 }}>→</span>
            </button>
            <button onClick={() => setActivePage('leaderboard')}
              style={{ padding:'9px 20px', background:'#fff', color:'#374151', borderRadius:8, border:'1px solid #d1d5db', fontWeight:600, fontSize:13, cursor:'pointer' }}>
              Leaderboard
            </button>
          </div>
        </div>
        {/* Robot illustration box — matches reference */}
        <div style={{ width:'100%', aspectRatio:'4/3', background:'linear-gradient(135deg,#ede9fe,#e0e7ff)', borderRadius:12, border:'1px solid #ddd6fe', display:'flex', alignItems:'center', justifyContent:'center', fontSize:56 }}>
          🤖
        </div>
      </div>

      {/* ── 4 STAT CARDS ── matches image */}
      <div style={{ display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:12, marginBottom:20 }}>
        {/* Exams Taken — plain white */}
        <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:12, padding:'16px 18px', boxShadow:'0 1px 3px rgba(0,0,0,.05)', display:'flex', justifyContent:'space-between', alignItems:'flex-start' }}>
          <div>
            <div style={{ fontSize:10, fontWeight:700, color:'#9ca3af', textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace', marginBottom:6 }}>EXAMS TAKEN</div>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:28, color:'#0f0f1a' }}>{progress.length}</div>
          </div>
          <span style={{ fontSize:20, opacity:.2 }}>📄</span>
        </div>

        {/* Avg Score — pink tint like image */}
        <div style={{ background:'linear-gradient(135deg,#fce7f3,#fff)',border:'1px solid #fbcfe8', borderRadius:12, padding:'16px 18px', boxShadow:'0 1px 3px rgba(0,0,0,.05)', display:'flex', justifyContent:'space-between', alignItems:'flex-start' }}>
          <div>
            <div style={{ fontSize:10, fontWeight:700, color:'#9ca3af', textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace', marginBottom:6 }}>AVG SCORE</div>
            <div style={{ display:'flex', alignItems:'baseline', gap:6 }}>
              <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:28, color:'#0f0f1a' }}>{avgPct}%</div>
              <span style={{ fontSize:11, color:'#9ca3af' }}>+2% since last week</span>
            </div>
          </div>
          <span style={{ fontSize:20, opacity:.25 }}>📊</span>
        </div>

        {/* Best Grade — cyan tint like image */}
        <div style={{ background:'linear-gradient(135deg,#cffafe,#fff)', border:'1px solid #a5f3fc', borderRadius:12, padding:'16px 18px', boxShadow:'0 1px 3px rgba(0,0,0,.05)', display:'flex', justifyContent:'space-between', alignItems:'flex-start' }}>
          <div>
            <div style={{ fontSize:10, fontWeight:700, color:'#9ca3af', textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace', marginBottom:6 }}>BEST GRADE</div>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:28, color:gc(bestGrade) }}>{bestGrade}</div>
          </div>
          <span style={{ fontSize:20, opacity:.25 }}>🏆</span>
        </div>

        {/* Department — violet tint like image */}
        <div style={{ background:'linear-gradient(135deg,#ede9fe,#fff)', border:'1px solid #ddd6fe', borderRadius:12, padding:'16px 18px', boxShadow:'0 1px 3px rgba(0,0,0,.05)', display:'flex', justifyContent:'space-between', alignItems:'flex-start' }}>
          <div>
            <div style={{ fontSize:10, fontWeight:700, color:'#9ca3af', textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace', marginBottom:6 }}>DEPARTMENT</div>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:20, color:'#0f0f1a' }}>
              {store.currentStudent?.department||'N/A'}
              <span style={{ fontSize:12, color:'#9ca3af', fontWeight:400, marginLeft:4 }}>{store.currentStudent?.year||''}</span>
            </div>
          </div>
          <span style={{ fontSize:20, opacity:.2 }}>🎓</span>
        </div>
      </div>

      {/* ── MAIN 2-COLUMN LAYOUT — matches image exactly ── */}
      <div style={{ display:'grid', gridTemplateColumns:'1fr 320px', gap:16 }}>

        {/* LEFT: Announcements */}
        <div>
          <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:'18px 20px', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
            <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:16 }}>
              <div style={{ display:'flex', alignItems:'center', gap:8 }}>
                <span style={{ fontSize:15 }}>🔔</span>
                <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#0f0f1a' }}>Announcements</span>
              </div>
              <button onClick={() => setActivePage('notifications')}
                style={{ fontSize:12, fontWeight:600, color:'#7c3aed', background:'none', border:'none', cursor:'pointer', display:'flex', alignItems:'center', gap:4 }}>
                View All <span>→</span>
              </button>
            </div>

            {notifs.length === 0 ? (
              <div style={{ textAlign:'center', padding:'32px 16px' }}>
                <div style={{ width:48, height:48, borderRadius:'50%', background:'#f3f4f6', border:'1px solid #e5e7eb', display:'flex', alignItems:'center', justifyContent:'center', margin:'0 auto 12px', fontSize:20, color:'#9ca3af' }}>ℹ</div>
                <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#374151', marginBottom:6 }}>No announcements yet</div>
                <div style={{ fontSize:12, color:'#9ca3af', marginBottom:16, lineHeight:1.6 }}>Stay tuned! Official updates from your<br/>department will appear here.</div>
                <button onClick={() => setActivePage('notifications')}
                  style={{ padding:'7px 18px', background:'#fff', color:'#374151', border:'1px solid #d1d5db', borderRadius:8, fontSize:12, fontWeight:600, cursor:'pointer' }}>
                  Check Updates
                </button>
              </div>
            ) : notifs.map(n => {
              const cfg = TYPE_COLORS[n.type]||TYPE_COLORS.info;
              return (
                <div key={n.notif_id} style={{ background:cfg.bg, border:`1px solid ${cfg.border}`, borderRadius:9, padding:'10px 14px', marginBottom:8 }}>
                  <div style={{ fontWeight:700, fontSize:13, color:cfg.c, marginBottom:3 }}>{n.title}</div>
                  <div style={{ fontSize:12, color:'#374151', lineHeight:1.5 }}>{n.message.slice(0,100)}{n.message.length>100?'...':''}</div>
                  <div style={{ fontSize:10, color:'#9ca3af', marginTop:4, fontFamily:'JetBrains Mono,monospace' }}>{new Date(n.created_at).toLocaleDateString()}</div>
                </div>
              );
            })}
          </div>

          {/* Recent Exam History — below announcements */}
          {progress.length > 0 && (
            <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)', marginTop:14 }}>
              <div style={{ padding:'14px 20px', borderBottom:'1px solid #f3f4f6', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                <div style={{ display:'flex', alignItems:'center', gap:8 }}>
                  <span style={{ fontSize:14 }}>🕐</span>
                  <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#0f0f1a' }}>Recent Exam History</span>
                </div>
                <button onClick={() => setActivePage('my-results')} style={{ fontSize:12, fontWeight:600, color:'#7c3aed', background:'none', border:'none', cursor:'pointer' }}>View Full History</button>
              </div>
              <table style={{ width:'100%', borderCollapse:'collapse', fontSize:12 }}>
                <thead>
                  <tr style={{ background:'#f8f8fc' }}>
                    {['EXAM NAME','DATE','SCORE','GRADE','ACTION'].map(h => (
                      <th key={h} style={{ padding:'9px 16px', textAlign:'left', fontSize:9, fontWeight:700, color:'#9ca3af', textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace', borderBottom:'1px solid #f3f4f6' }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {[...progress].reverse().slice(0,4).map((p,i) => {
                    const pct = Math.round(Number(p.total_score)/Number(p.total_marks)*100);
                    const color = gc(p.grade);
                    return (
                      <tr key={i} style={{ borderBottom:'1px solid #f3f4f6' }}
                        onMouseEnter={e=>e.currentTarget.style.background='#f8f8fc'}
                        onMouseLeave={e=>e.currentTarget.style.background='transparent'}>
                        <td style={{ padding:'11px 16px', fontWeight:600, color:'#0f0f1a' }}>{p.title}</td>
                        <td style={{ padding:'11px 16px', color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', fontSize:11 }}>{p.submit_time?new Date(p.submit_time).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'-'}</td>
                        <td style={{ padding:'11px 16px', color, fontWeight:700, fontFamily:'JetBrains Mono,monospace' }}>{pct}%</td>
                        <td style={{ padding:'11px 16px' }}>
                          <span style={{ padding:'2px 8px', borderRadius:4, background:`${color}15`, color, fontSize:10, fontWeight:800 }}>{p.grade}</span>
                        </td>
                        <td style={{ padding:'11px 16px' }}>
                          <button onClick={() => setActivePage('my-results')} style={{ fontSize:11, fontWeight:600, color:'#7c3aed', background:'none', border:'none', cursor:'pointer' }}>Review</button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* RIGHT: Recent Performance + Top Rankers stacked */}
        <div style={{ display:'flex', flexDirection:'column', gap:14 }}>

          {/* Recent Performance */}
          <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:'18px 20px', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
            <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:4 }}>
              <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#0f0f1a' }}>Recent Performance</div>
            </div>
            <div style={{ fontSize:10, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', textTransform:'uppercase', letterSpacing:1.5, marginBottom:14 }}>SUBJECT PROGRESS</div>

            {progress.length === 0 ? (
              <div style={{ textAlign:'center', padding:'20px 0', fontSize:12, color:'#9ca3af' }}>No exam history yet</div>
            ) : [...progress].reverse().slice(0,4).map((p,i) => {
              const pct = Math.round(Number(p.total_score)/Number(p.total_marks)*100);
              const color = gc(p.grade);
              return (
                <div key={i} style={{ marginBottom:i<3?14:0 }}>
                  <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:5 }}>
                    <div style={{ display:'flex', alignItems:'center', gap:8 }}>
                      <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:600, fontSize:13, color:'#0f0f1a' }}>{p.title}</span>
                      <span style={{ padding:'1px 7px', borderRadius:4, background:`${color}15`, color, fontSize:10, fontWeight:800 }}>{p.grade}</span>
                    </div>
                    <span style={{ fontSize:12, fontFamily:'JetBrains Mono,monospace', color:'#9ca3af' }}>{pct}%</span>
                  </div>
                  <div style={{ height:5, background:'#f3f4f6', borderRadius:3, overflow:'hidden' }}>
                    <div style={{ height:'100%', width:`${pct}%`, background:`linear-gradient(90deg,${color}88,${color})`, borderRadius:3 }}/>
                  </div>
                </div>
              );
            })}

            <button onClick={() => setActivePage('profile')}
              style={{ marginTop:14, display:'flex', alignItems:'center', gap:6, fontSize:12, color:'#7c3aed', fontWeight:600, background:'none', border:'none', cursor:'pointer', padding:0 }}>
              <span>📈</span> View Progress Graph <span>→</span>
            </button>
          </div>

          {/* Top Rankers */}
          <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:'18px 20px', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
            <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:14 }}>
              <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#0f0f1a' }}>Top Rankers</span>
              <span style={{ fontSize:18, opacity:.3 }}>🏆</span>
            </div>

            {topRanks.length === 0 ? (
              <div style={{ textAlign:'center', padding:'16px 0', fontSize:12, color:'#9ca3af' }}>No rankings yet</div>
            ) : topRanks.map((r,i) => (
              <div key={i} style={{ display:'flex', alignItems:'center', gap:10, padding:'8px 0', borderBottom:i<topRanks.length-1?'1px solid #f3f4f6':'none' }}>
                {/* Rank number/medal */}
                <div style={{ width:22, textAlign:'center', fontSize:i<3?15:12, fontWeight:800, color:rankColor(i), flexShrink:0 }}>
                  {rankMedal(i) || <span style={{ color:'#9ca3af' }}>{i+1}</span>}
                </div>
                {/* Avatar */}
                <div style={{ width:32, height:32, borderRadius:'50%', background:`${rankColor(i)}18`, border:`1.5px solid ${rankColor(i)}33`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:13, fontWeight:800, color:rankColor(i), flexShrink:0 }}>
                  {r.name?.charAt(0).toUpperCase()}
                </div>
                {/* Name */}
                <div style={{ flex:1, fontFamily:'Space Grotesk,sans-serif', fontWeight:600, fontSize:13, color:'#0f0f1a', whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>
                  {r.name}
                </div>
                {/* Score */}
                <div style={{ fontSize:12, fontWeight:800, color:'#7c3aed', flexShrink:0, fontFamily:'JetBrains Mono,monospace' }}>
                  {Number(r.total_score).toFixed(0)} <span style={{ fontSize:9, color:'#9ca3af', fontWeight:400 }}>pts</span>
                </div>
              </div>
            ))}
          </div>

        </div>
      </div>
    </div>
  );
}
